from tsurara_plugin import PyFile


def test_imports_are_sorted_and_the_marker_comes_first() -> None:
    f = PyFile("hooks/get_pet.py")
    fn = f.import_from("..operations.get_pet", "get_pet")
    f.import_from("tsurara_client", "Client")
    f.line(f"x = {fn}")
    assert f.render("# Generated by tsurara. Do not edit.") == (
        "# Generated by tsurara. Do not edit.\n\nfrom ..operations.get_pet import get_pet\nfrom tsurara_client import Client\n\n\nx = get_pet\n"
    )
